create schema if not exists private;
create extension if not exists pgcrypto;
create table if not exists public.schools(id uuid primary key default gen_random_uuid(),name text not null,directeur text not null,telephone text,adresse text,created_at timestamptz default now());
create table if not exists public.school_members(user_id uuid primary key references auth.users(id) on delete cascade,school_id uuid not null references public.schools(id) on delete cascade,role text not null default 'directeur',created_at timestamptz default now());
create table if not exists public.classes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,nom text not null,frais_scolarite_total numeric(12,2) not null default 0);
create table if not exists public.students(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,class_id uuid references public.classes(id) on delete set null,nom_complet text not null,matricule text not null,nom_parent text,telephone_parent text,created_at timestamptz default now(),unique(school_id,matricule));
create table if not exists public.paiements(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,montant_paye numeric(12,2) not null check(montant_paye>0),date_paiement date not null default current_date,mode_paiement text not null default 'Espèces',mois_concerne text,recu_numero text unique not null,created_at timestamptz default now());
create table if not exists public.annee_scolaire(id uuid primary key default gen_random_uuid(),libelle text not null unique,status text not null default 'inactive');
create or replace function private.is_school_member(school uuid) returns boolean language sql security definer set search_path=public,private stable as $$ select exists(select 1 from public.school_members where user_id=(select auth.uid()) and school_id=school); $$;
revoke all on function private.is_school_member(uuid) from public; grant execute on function private.is_school_member(uuid) to authenticated;
alter table public.schools enable row level security;alter table public.school_members enable row level security;alter table public.classes enable row level security;alter table public.students enable row level security;alter table public.paiements enable row level security;alter table public.annee_scolaire enable row level security;
create policy "school members read own school" on public.schools for select to authenticated using(private.is_school_member(id));
create policy "authenticated create school" on public.schools for insert to authenticated with check(true);
create policy "members update school" on public.schools for update to authenticated using(private.is_school_member(id)) with check(private.is_school_member(id));
create policy "member sees membership" on public.school_members for select to authenticated using(user_id=(select auth.uid()));
create policy "user joins own school" on public.school_members for insert to authenticated with check(user_id=(select auth.uid()));
create policy "classes own school" on public.classes for all to authenticated using(private.is_school_member(school_id)) with check(private.is_school_member(school_id));
create policy "students own school" on public.students for all to authenticated using(private.is_school_member(school_id)) with check(private.is_school_member(school_id));
create policy "payments own school" on public.paiements for all to authenticated using(exists(select 1 from public.students s where s.id=student_id and private.is_school_member(s.school_id))) with check(exists(select 1 from public.students s where s.id=student_id and private.is_school_member(s.school_id)));
create policy "active academic year read" on public.annee_scolaire for select to authenticated using(true);
create index if not exists students_school_idx on public.students(school_id);create index if not exists students_class_idx on public.students(class_id);create index if not exists payments_student_idx on public.paiements(student_id);